public class TextAnalyzerBenchmarks
{
    private TextAnalyzer _analyzer = null!;

    [GlobalSetup]
    public void Setup()
    {
        // Generate a representative text with ~1000 words
        var words = new string[]
        {
            "the", "quick", "brown", "fox", "jumps", "over", "lazy", "dog",
            "performance", "benchmarking", "is", "important", "for", "understanding",
            "how", "code", "behaves", "under", "different", "runtime", "versions",
            "optimization", "algorithms", "data", "structures", "complexity"
        };
